Action: run_sql({'query': "\nWITH cat as (\n  SELECT e.gmap_id, e.avg_rating, e.slchd_establishment_key,\n    CASE WHEN c.category ilike '%thai%' THEN 'Thai'\n         WHEN c.category ilike '%korean%' THEN 'Korean' END as cuisine\n  FROM establishments e\n  JOIN establishment_categories ec ON ec.gmap_id = e.gmap_id\n  JOIN category c ON c.category_id = ec.category_id\n  WHERE c.category ilike '%thai%' OR c.category ilike '%korean%'\n)\nSELECT cuisine, count(distinct gmap_id) as n_establishments, avg(avg_rating) as avg_rating\nFROM cat\nGROUP BY cuisine\n"})

Action: run_sql({'query': "\nWITH cat as (\n  SELECT DISTINCT e.gmap_id, e.slchd_establishment_key,\n    CASE WHEN c.category ilike '%thai%' THEN 'Thai'\n         WHEN c.category ilike '%korean%' THEN 'Korean' END as cuisine\n  FROM establishments e\n  JOIN establishment_categories ec ON ec.gmap_id = e.gmap_id\n  JOIN category c ON c.category_id = ec.category_id\n  WHERE c.category ilike '%thai%' OR c.category ilike '%korean%'\n)\nSELECT cat.cuisine,\n  count(distinct cat.gmap_id) as n_establishments,\n  count(distinct cat.slchd_establishment_key) filter (where cat.slchd_establishment_key is not null) as n_matched,\n  count(v.violation_id) as total_violations,\n  count(v.violation_id) filter (where vc.critical) as critical_violations\nFROM cat\nLEFT JOIN inspections i ON i.slchd_establishment_key = cat.slchd_establishment_key\nLEFT JOIN violations v ON v.inspection_id = i.inspection_id\nLEFT JOIN violation_codes vc ON vc.violation_code_id = v.violation_code_id\nGROUP BY cat.cuisine\n"})

